CREATE TABLE mcp_event_locator (`event_uid` String, `event_version` UInt64, `ingested_at` DateTime64(3), `session_id` String, `source_name` LowCardinality(String), `source_file` String, `source_generation` UInt32, `source_offset` UInt64, `source_line_no` UInt64, `sort_time` DateTime64(3), `doc_len` UInt32, `text_digest` String, `payload_phase` LowCardinality(String), `project_id` String, `repo_rel_path` String, `worktree_root` String, `path_tokens` Array(String), `has_codex_mcp` UInt8) ENGINE = ReplacingMergeTree(event_version) ORDER BY event_uid SETTINGS index_granularity = 8192
